contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address callee, bytes calldata data) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(true);
        // record balances before
        uint256 beforeTest = address(this).balance;
        uint256 beforeC = address(c).balance;

        bool reverted;
        // perform the state-changing call on c at top level
        c.forward(callee, data); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterTest = address(this).balance;
        uint256 afterC = address(c).balance;

        // Assert the general rule: if not reverted then external call must have succeeded (forward only returns on success)
        // and balances of test contract and C are unchanged when forward returns.
        assert((reverted == true) || (reverted == false && afterTest == beforeTest && afterC == beforeC));
    }
    receive() external payable { }
}

